      + '\n' + validation + '\n' + scatterLine + '\nreturn { BATCH, BATCH_RECORD, RUNGS, SCATTER, BATCH_INTRO, BATCH_OVERLAPS, LEDGER_FROM }')()
    try { evalWith(null); console.log('LEDGER_FROM unset: did NOT throw (bad)'); bad++ } catch (e) { console.log('LEDGER_FROM unset: throws: ' + e.message) }
    const r = evalWith(456)
